"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { Collapsible, CollapsibleContent, CollapsibleList, CollapsibleTrigger } from "@/components/ui/collapsible"
import { Item, ItemActions, ItemTitle } from "@/components/ui/item"

type TreeNode = {
  id: string
  label: React.ReactNode
  /** A folder holds children; a node without them is a leaf. An empty array is an empty folder. */
  children?: TreeNode[]
  /** Set at the end of the line after a dotted leader, as a contents page sets its page numbers: a size, a count, a folio. */
  value?: React.ReactNode
  /** A leaf that goes somewhere is a link. */
  href?: string
}

type TreeProps = Omit<React.ComponentProps<"div">, "children"> & {
  nodes: TreeNode[]
  /**
   * branch: a hairline spine hangs from under each open folder's first letter and every name sits on it at a dot; a
   * closed folder is a ring, an open one a filled dot, the chosen leaf the accent. outline: the book's decimal
   * contents, each name numbered by its place (1, 1.2, 1.2.3) in a pencil column, and no lines at all.
   */
  variant?: "branch" | "outline"
  /** The chosen leaf's id, controlled or not. */
  selected?: string | null
  defaultSelected?: string | null
  onSelectedChange?: (id: string) => void
  /** The open folders' ids, controlled or not. */
  expanded?: string[]
  defaultExpanded?: string[]
  onExpandedChange?: (ids: string[]) => void
  /** A folder longer than this shows its first rows, then "and 6 more", as a collapsible does. */
  limit?: number
}

type Ctx = { selected: string | null; select: (id: string) => void; open: Set<string>; toggle: (id: string, open: boolean) => void; limit: number; touched: React.RefObject<boolean> }
const TreeCtx = React.createContext<Ctx | null>(null)

const CONTROLS = "summary, .db-tree-name"

/**
 * A hierarchy you open a folder at a time: native disclosures, so every folder opens with Enter or Space and Tab
 * walks it. The arrows walk it too, as a tree: up and down through what shows, right to open or step in, left to
 * close or step out, Home and End to the ends.
 */
function Tree({ nodes, variant = "branch", selected, defaultSelected = null, onSelectedChange, expanded, defaultExpanded = [], onExpandedChange, limit = Infinity, className, onKeyDown, ...props }: TreeProps) {
  const [ownSelected, setOwnSelected] = React.useState(defaultSelected)
  const [ownOpen, setOwnOpen] = React.useState(() => new Set(defaultExpanded))
  const touched = React.useRef(false) // a folder that opens before anyone touches the tree (open from the start) doesn't play its arrival
  const open = React.useMemo(() => (expanded ? new Set(expanded) : ownOpen), [expanded, ownOpen])

  const ctx: Ctx = {
    selected: selected === undefined ? ownSelected : selected,
    select(id) {
      if (selected === undefined) setOwnSelected(id)
      onSelectedChange?.(id)
    },
    open,
    toggle(id, now) {
      if (open.has(id) === now) return
      const next = new Set(open)
      if (now) next.add(id)
      else next.delete(id)
      if (!expanded) setOwnOpen(next)
      onExpandedChange?.([...next])
    },
    limit,
    touched,
  }

  function walk(e: React.KeyboardEvent<HTMLDivElement>) {
    onKeyDown?.(e)
    const at = e.target as HTMLElement
    if (e.defaultPrevented || e.altKey || e.ctrlKey || e.metaKey || !at.matches(CONTROLS)) return
    const all = [...e.currentTarget.querySelectorAll<HTMLElement>(CONTROLS)].filter((el) => el.checkVisibility())
    const i = all.indexOf(at)
    const rtl = getComputedStyle(at).direction === "rtl"
    const key = rtl ? ({ ArrowLeft: "ArrowRight", ArrowRight: "ArrowLeft" } as Record<string, string>)[e.key] ?? e.key : e.key
    const folder = at.localName === "summary" ? (at.parentElement as HTMLDetailsElement) : null
    let to: HTMLElement | null | undefined
    if (key === "ArrowDown") to = all[i + 1]
    else if (key === "ArrowUp") to = all[i - 1]
    else if (key === "Home") to = all[0]
    else if (key === "End") to = all.at(-1)
    else if (key === "ArrowRight" && folder) {
      if (!folder.open) folder.open = true
      else to = all[i + 1]
    } else if (key === "ArrowLeft") {
      if (folder?.open) folder.open = false
      else to = (folder ?? at).parentElement?.closest("details")?.querySelector<HTMLElement>(":scope > summary")
    } else return
    e.preventDefault()
    to?.focus()
  }

  return (
    <TreeCtx.Provider value={ctx}>
      <div
        data-slot="tree"
        data-variant={variant === "branch" ? undefined : variant}
        className={cn("db-tree", className)}
        onKeyDown={walk}
        onPointerDownCapture={() => void (touched.current = true)}
        onKeyDownCapture={() => void (touched.current = true)}
        {...props}
      >
        <Branch nodes={nodes} />
      </div>
    </TreeCtx.Provider>
  )
}

function Branch({ nodes }: { nodes: TreeNode[] }) {
  const { limit } = React.useContext(TreeCtx)!
  const cut = nodes.length > limit ? Math.max(1, limit) : nodes.length
  const rest = nodes.slice(cut)
  return (
    <ul className="db-tree-list">
      {nodes.slice(0, cut).map((n) => (
        <Node key={n.id} node={n} />
      ))}
      {rest.length ? (
        <li className="db-tree-tail">
          <Collapsible>
            <CollapsibleTrigger openLabel={`Hide these ${rest.length}`}>and {rest.length} more</CollapsibleTrigger>
            <CollapsibleContent>
              <CollapsibleList>
                {rest.map((n) => (
                  <Node key={n.id} node={n} />
                ))}
              </CollapsibleList>
            </CollapsibleContent>
          </Collapsible>
        </li>
      ) : null}
    </ul>
  )
}

function Node({ node }: { node: TreeNode }) {
  const { selected, select, open, toggle, touched } = React.useContext(TreeCtx)!
  const [arriving, setArriving] = React.useState(false)
  const end = node.value === undefined ? null : <ItemActions>{node.value}</ItemActions>

  if (!node.children) {
    const current = selected === node.id
    const name = <ItemTitle>{node.label}</ItemTitle>
    return (
      <Item className="db-tree-node db-tree-row" data-kind="leaf" data-selected={current ? "" : undefined}>
        {node.href ? (
          <a className="db-tree-name" href={node.href} aria-current={current ? "page" : undefined} onClick={() => select(node.id)}>
            {name}
          </a>
        ) : (
          <button type="button" className="db-tree-name" aria-current={current ? "true" : undefined} onClick={() => select(node.id)}>
            {name}
          </button>
        )}
        {end}
      </Item>
    )
  }

  const n = node.children.length
  return (
    <li className="db-tree-node" data-kind="folder">
      <details
        className="db-tree-folder"
        open={open.has(node.id)}
        data-arriving={arriving ? "" : undefined}
        onToggle={(e) => {
          if (e.target !== e.currentTarget) return // a tail's toggle inside bubbles up
          const now = e.currentTarget.open
          setArriving(now && touched.current)
          toggle(node.id, now)
        }}
      >
        <summary className="db-tree-row">
          <ItemTitle>
            {node.label}
            <sup className="db-tree-count" aria-hidden="true">{n}</sup>
            <span className="db-sr">, {n === 1 ? "1 item" : `${n} items`}</span>
          </ItemTitle>
          {end}
        </summary>
        {n ? <Branch nodes={node.children} /> : <p className="db-tree-empty">Empty</p>}
      </details>
    </li>
  )
}

export { Tree, type TreeProps, type TreeNode }

@layer components {
  /* ── db-tree ── a hierarchy set as a contents page: names on hairline branches. Each open folder's branch hangs from under the
     first letter of its name, and every name sits on it at a dot, so the depth is read off the lines, not from boxes or icons.
     A leaf is a small graphite dot, a closed folder a ring, an open one a filled dot; the chosen leaf is the one accent and
     its name turns italic. A value (a size, a folio) is joined to its name by the item's leader. */
  .db-tree {
    --db-tree-pad: var(--db-space-2); /* a row's padding above and below its name */
    --db-tree-indent: var(--db-space-5); /* from a dot to its name, and so from a branch to the next one in */
    --d: 7px;
    padding-inline-start: calc(var(--d) / 2); min-width: 0;
    font-size: var(--db-p); line-height: var(--db-p-lh); letter-spacing: var(--db-p-tr);
  }
  .db-tree-list { list-style: none; margin: 0; padding: 0; }
  .db-tree-list .db-tree-list { padding-inline-start: var(--db-tree-indent); }

  .db-tree .db-tree-node { position: relative; padding: 0; border: 0; }
  .db-tree .db-tree-row { position: relative; display: flex; align-items: baseline; gap: var(--db-space-4); padding-block: var(--db-tree-pad); padding-inline-start: var(--db-tree-indent); border: 0; }
  .db-tree-folder > summary { list-style: none; cursor: pointer; -webkit-tap-highlight-color: transparent; }
  .db-tree-folder > summary::-webkit-details-marker { display: none; }

  /* The branch: each row carries its own length of it, the last one stopping at its dot. */
  .db-tree-node::before, .db-tree-tail::before {
    content: ""; position: absolute; inset-block: 0; inset-inline-start: calc(var(--db-hairline) / -2); inline-size: var(--db-hairline);
    background: var(--db-rule-strong); transform-origin: top;
  }
  :is(.db-tree-list, .db-tree .db-collapse-list) > :is(.db-tree-node, .db-tree-tail):last-child::before { inset-block-end: auto; block-size: calc(var(--db-tree-pad) + 0.5lh); }
  .db-tree > .db-tree-list > :first-child::before { inset-block-start: calc(var(--db-tree-pad) + 0.5lh); } /* the root's branch starts at its first name */
  .db-tree > .db-tree-list > :only-child::before { content: none; }
  .db-tree-list > .db-tree-tail:has(> .db-collapse[open])::before { block-size: calc(2 * var(--db-tree-pad) + 1lh); }

  /* The dots */
  .db-tree-row::after {
    content: ""; position: absolute; box-sizing: border-box; inset-inline-start: calc(var(--d) / -2); inset-block-start: calc(var(--db-tree-pad) + 0.5lh - var(--d) / 2);
    inline-size: var(--d); block-size: var(--d); border-radius: 50%; border: var(--db-hairline) solid var(--c, var(--db-graphite)); background: var(--c, var(--db-graphite));
    scale: 0.6; transition: scale var(--db-moderato) var(--db-spiccato), background-color var(--db-allegro), border-color var(--db-allegro);
  }
  .db-tree-folder > .db-tree-row::after { --c: var(--db-ink); scale: 1; background: var(--db-paper); }
  .db-tree-folder[open] > .db-tree-row::after { background: var(--db-ink); }
  .db-tree-row[data-selected]::after { --c: var(--db-accent); scale: 1; }

  /* The names: folders set firm, leaves in graphite that inks as you point; the chosen one italic, as yours. */
  .db-tree-name { appearance: none; margin: 0; padding: 0; border: 0; background: none; font: inherit; letter-spacing: inherit; color: var(--db-graphite); text-align: start; text-decoration: none; cursor: pointer; transition: color var(--db-allegro); }
  .db-tree-row:is(:hover, :focus-within, [data-force~="hover"]) .db-tree-name, .db-tree-name[aria-current] { color: var(--db-ink); }
  .db-tree-name[aria-current] .db-item-title { font-style: italic; }
  .db-tree-folder > summary .db-item-title { font-weight: 500; }
  .db-tree-count { margin-inline-start: 0.2em; font-size: var(--db-pp); font-weight: 400; font-variant-numeric: tabular-nums; color: var(--db-pencil); }
  .db-tree .db-item-end { color: var(--db-graphite); }
  .db-tree-folder > summary:is(:hover, :focus-visible, [data-force~="hover"]) .db-item-leader::after { mask-position: 0 0; mask-size: 100% 100%; }
  .db-tree-empty { margin: 0; padding-block: var(--db-tree-pad); padding-inline-start: calc(2 * var(--db-tree-indent)); font-size: var(--db-pp); color: var(--db-pencil); }

  /* A long folder ends in the rest of itself, as the collapsible does: "and 6 more" stands on the branch's end. */
  .db-tree-tail { position: relative; }
  .db-tree .db-tree-tail > .db-collapse:is(*, [open]) > summary { --py: var(--db-tree-pad); display: flex; inline-size: fit-content; margin-block: 0; margin-inline: var(--db-tree-indent) 0; line-height: inherit; }
  .db-tree .db-collapse-list > li { padding-block: 0; border: 0; }
  .db-tree .db-tree-tail > .db-collapse::details-content { overflow-clip-margin: var(--d); } /* the rest's dots and branch stand on its edge */
  .db-tree .db-collapse-list > .db-tree-row { padding-block: var(--db-tree-pad); }

  /* Opening a folder: its branch draws down and its names arrive in turn under it. Not for folders open from the start. */
  .db-tree-folder::details-content { block-size: 0; overflow: clip; transition: block-size var(--db-andante) var(--db-exhale), content-visibility var(--db-andante) allow-discrete; }
  .db-tree-folder[open]::details-content { block-size: auto; }
  .db-tree-folder[data-arriving][open] > .db-tree-list > li { animation: db-arrive var(--db-moderato) var(--db-exhale) backwards; animation-delay: calc(sibling-index() * 2 * var(--db-arpeggio)); }
  .db-tree-folder[data-arriving][open] > .db-tree-list > li::before { animation: db-draw-y var(--db-andante) var(--db-exhale) backwards; animation-delay: calc((sibling-index() - 1) * 2 * var(--db-arpeggio)); }

  /* ── outline ── the book's decimal contents: every name numbered by its place (1, 1.2, 1.2.3) in a pencil column, flush to one
     edge at every depth, and no lines; the depth is in the numbers. An open folder's number inks; the chosen leaf's is the accent. */
  .db-tree[data-variant="outline"] { --db-tree-indent: calc(3em + var(--db-space-4)); padding-inline-start: 0; }
  .db-tree[data-variant="outline"] .db-tree-list { padding-inline-start: 0; counter-reset: db-tree; }
  .db-tree[data-variant="outline"] .db-tree-node { counter-increment: db-tree; }
  .db-tree[data-variant="outline"] :is(.db-tree-node, .db-tree-tail)::before { content: none; }
  .db-tree[data-variant="outline"] .db-tree-row { padding-inline-start: 0; }
  .db-tree[data-variant="outline"] .db-tree-row::after {
    content: counters(db-tree, ".") / ""; position: static; order: -1; flex: none; inline-size: 3em; block-size: auto; scale: 1;
    border: 0; border-radius: 0; background: none; font-variant-numeric: tabular-nums; color: var(--c, var(--db-pencil)); transition: color var(--db-allegro);
  }
  .db-tree[data-variant="outline"] .db-tree-folder[open] > .db-tree-row::after { --c: var(--db-ink); }
  .db-tree[data-variant="outline"] .db-tree-row[data-selected]::after { --c: var(--db-accent); }
  .db-tree[data-variant="outline"] .db-tree-list .db-tree-list .db-tree-folder > summary .db-item-title { font-weight: 400; }
  .db-tree[data-variant="outline"] > .db-tree-list > .db-tree-node > .db-tree-folder > summary .db-item-title { font-weight: 600; }
}
